import{esc,button,input,range,select}from'../phase4/ui.js';
import{counts,factAnswer,number}from'./b13-model.js';
const f=(key,label,value)=>input(key,label,value,'autocomplete="off" spellcheck="false"');
const dots=(rows,cols,cut=null)=>`<div class="b13-array" style="--cols:${Math.max(1,cols)}" role="img" aria-label="${rows}行，每行${cols}格">${Array.from({length:rows*cols},(_,i)=>`<i class="${cut!==null&&i%cols>=cut?'other':''}" style="${cut!==null&&i%cols===cut?'border-left:3px solid #597b62;':''}"></i>`).join('')}</div>`;
const token=(m,i)=>button('b13-token','●',`data-token="${i}" data-b13-token="${i}" draggable="true" aria-label="第${i+1}个物品" aria-pressed="${m.board.selected.includes(i)}"`);
const expression=c=>c.kind==='parity'?`${c.n} 能全部两两配好吗？`:`${c.a} ${c.op} ${c.b}`;
const answerText=(c,a)=>c.kind==='parity'?(a==='even'?'偶数 · 没有剩余':'奇数 · 剩一个'):a;
const pending=m=>m.board.built&&(number(m.rows)!==m.board.built.rows||number(m.cols)!==m.board.built.cols);
function groups(t,m){const b=m.board;return `<div class="b13-pool" data-b13-bucket="-1"><span>${t.mode==='build'?'桌面上可以取一些物品':'还在桌上的物品'}</span><div class="b13-tokens">${b.homes.flatMap((v,i)=>v===-1?[token(m,i)]:[]).join('')}</div>${b.selected.length?button('b13-drop','搬回桌面','data-bucket="-1"'):''}</div><div class="b13-plates">${Array.from({length:b.buckets},(_,n)=>`<section class="b13-plate" data-b13-bucket="${n}"><b>第 ${n+1} 份</b><div class="b13-tokens">${b.homes.flatMap((v,i)=>v===n?[token(m,i)]:[]).join('')||'<span class="b13-empty">空着</span>'}</div>${button('b13-pour','放到这里',`data-bucket="${n}" aria-label="放到第${n+1}份"`)}</section>`).join('')}</div>`;}
function sharePicture(n,d){const per=n/d,units=Math.max(1,Math.ceil(per));return `<div class="b13-div-picture" aria-label="${n}个平均分给${d}组"><span>${n} 个 → ${d} 组</span><div class="b13-div-plates">${Array.from({length:d},()=>`<div class="b13-div-strip" style="width:${units*38}px"><i style="width:${per/units*100}%"></i>${Array.from({length:units-1},(_,i)=>`<em style="left:${(i+1)/units*100}%"></em>`).join('')}</div>`).join('')}</div><small>每个小框代表 1 个；不足一框就是不到 1 个。</small></div>`;}
export function visual(t,m){const b=m.board;switch(t.type){
 case'x-mulgroups':return groups(t,m);
 case'x-mularray':{const r=number(m.rows)||0,c=number(m.cols)||0,shape=b.built&&!pending(m)?dots(b.rows,b.cols,b.cut):dots(Math.min(r,12),Math.min(c,12));return `<div class="b13-array-scene">${shape||''}${!r||!c?'<p>先拉出行和列。</p>':''}${(t.unit||1)!==1?`<p class="b13-unit">每一格代表 ${t.unit}，相同大小的图也可以代表不同的量。</p>`:''}${b.turns&&!pending(m)?`<p class="b13-record">原来 ${b.built.rows} 行，每行 ${b.built.cols}；转向后 ${b.rows} 行，每行 ${b.cols}。</p>`:''}${b.cut!==null&&!pending(m)?`<p class="b13-record">${b.rows} 行 × 左边 ${b.cut} 列　＋　${b.rows} 行 × 右边 ${b.cols-b.cut} 列</p>`:''}</div>`;}
 case'x-mulfacts':{const c=t.cases[b.saved.length];let help='';if(c&&b.help){if(c.kind==='parity')help=`<p>整十的部分可以全部配好，再看最后 ${c.n%10} 颗。</p>${dots(1,c.n%10)}`;else{const r=c.op==='×'?c.a:c.a/c.b,cols=c.b;help=dots(r,cols);}}return `${c?`<p class="b13-fact">${expression(c)}</p>`:'<p class="b13-fact">这一小组都留下了。</p>'}${help}<div class="b13-fact-records">${b.saved.map((s,i)=>`<span>${expression(t.cases[i])} → ${answerText(t.cases[i],s.answer)}</span>`).join('')}</div>`;}
 case'x-factorrects':{const r=number(m.rows)||0,c=number(m.cols)||0;return `<div class="b13-array-scene">${r*c<=t.n*2?dots(r,c):'<p>这幅图放得太多了。缩短一边再试。</p>'}</div><div class="b13-pair-records">${b.pairs.map(p=>`<span>${p[0]} × ${p[1]}</span>`).join('')}</div>`;}
 case'x-mulchain':return `<div class="b13-chain">${b.groups.map((g,i)=>`<section>${button('b13-chain-pick',String(g.value),`data-index="${i}" aria-pressed="${b.selected.includes(i)}" ${b.groups.length===1?'disabled':''}`)}<small>${g.ids.map(j=>t.values[j]).join(' × ')}</small></section>`).join('')}</div><ol class="b13-trail">${b.merges.map(s=>`<li>${s.left.value} × ${s.right.value} = ${esc(s.result)}</li>`).join('')}</ol>`;
 case'x-divreverse':return sharePicture(b.swaps%2?t.b:t.a,b.swaps%2?t.a:t.b);
}return'';}
export function controls(t,m){const b=m.board;switch(t.type){
 case'x-mulgroups':return `<div class="b13-build-controls">${t.mode!=='share'?button('b13-plate-add','添一个空盘',b.buckets>=12?'disabled':'')+button('b13-plate-remove','收起最后一个空盘',!b.buckets?'disabled':''):button('b13-round','每盘再放一个')}${f('amount','这次取几个放入一份',m.amount)}</div><p class="b13-small">可以拖动；也可以先点几颗，再点要去的盘子。</p>${f('answer',t.mode==='build'?'全部有多少':t.mode==='share'?'每份有多少':'有几份',m.answer)}${t.remainder?f('rest','还剩几颗',m.rest):''}${f('equation',t.remainder?'用“份数 × 每份 + 剩余 = 全部”写关系':'写一个与问题对应的算式',m.equation)}${t.repeated?f('addition','把每份写成连加（包含等号和总数）',m.addition):''}${button('b13-reset','重新摆，保留之前的尝试')}`;
 case'x-mularray':return `<div class="b13-dimensions">${range('rows','行数',m.rows,0,12)}${range('cols','每行几格',m.cols,0,12)}${t.rotate?select('prediction','先猜转向后数量会怎样',m.prediction,[['more','变多'],['less','变少'],['same','不变']]):''}${button('b13-shape','摆成这样')}</div>${t.rotate&&b.built?button('b13-turn','把整幅图转向'):''}${t.split&&b.built?`<div class="b13-cut">${range('cut','切线放在第几列后面',m.cut,0,b.cols)}${button('b13-cut','沿这里分成两块')}${f('left','左边这块有多少',m.left)}${f('right','右边这块有多少',m.right)}</div>`:''}${t.repeated?f('addition','按当前的行写连加算式',m.addition):''}${(t.unit||1)!==1?f('base','先数有几格这样的单位',m.base):''}${f('equation',t.approximate?'用 ≈ 写出估算关系':t.hidden?'用 □ 或 ? 写出含未知量的关系':'写一个对应的乘法算式',m.equation)}${f('answer',t.hidden?'空格里是多少':t.approximate?'大约是多少':'全部是多少',m.answer)}${t.original?f('check',`把找到的数放回 ${esc(t.original)}，写完整等式检查`,m.check):''}`;
 case'x-mulfacts':{const c=t.cases[b.saved.length];return c?(c.kind==='parity'?select('answer','能全部配好吗',m.answer,[['even','能，偶数'],['odd','会剩一个，奇数']]):f('answer','先自己想，再留下结果',m.answer))+button('b13-fact-save','留下，再换一组')+button('b13-fact-help','用图找回来'):'';}
 case'x-factorrects':return `<div class="b13-dimensions">${range('rows','行数',m.rows,0,t.n)}${range('cols','每行多少',m.cols,0,t.n)}</div>${f('answer','这一种摆法一共有多少',m.answer)}${button('b13-pair-save','把这种摆法留下')}`;
 case'x-mulchain':return b.groups.length>1?f('result','选中的两份相乘得到多少',m.result)+button('b13-chain-merge','先合这一对',b.selected.length!==2?'disabled':'')+(b.merges.length?button('b13-chain-undo','退一步换个搭档'):''):f('answer','三个原数相乘，最后是多少',m.answer)+button('b13-chain-undo','退一步换个搭档');
 case'x-divreverse':return f('answer',`原来 ${t.a} ÷ ${t.b}，每组多少`,m.answer)+button('b13-div-swap','交换全部和组数')+(b.swaps?f('result',`换成 ${t.b} ÷ ${t.a}，每组多少（可写分数）`,m.result):'');
}return'';}
export const render=(t,m)=>`<section class="b13-work"><div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}${m.issue?`<p class="b13-issue" role="status">${esc(m.issue)}</p>`:''}</div></section>`;

export function syncControls(t,m,root){if(t.type!=='x-mularray'||!root)return;for(const el of root.querySelectorAll('[data-x="b13-turn"],[data-x="b13-cut"],.b13-cut [data-xfield]'))el.disabled=!!pending(m);}
